#!/usr/bin/env python3
"""Create the Alipay + 88VIP Notion system under a target Notion page.

This script is intentionally API-first and conservative:
- It creates one dashboard child page under the target page.
- It creates three databases under the dashboard page: Actions, Checklist, Rules.
- It creates future six-month action rows and detailed checklist rows.
- It writes real to-do blocks inside each Action page so the user can tick items immediately.

Notion native reminders can be configured in the UI on the database Date property. The public
API does not expose a guaranteed reminder toggle as of the docs used by this pack, so this script
creates exact Date values and reminder instructions, but does not claim to enable native reminders.
"""
from __future__ import annotations

import argparse
import csv
import json
import os
import re
import sys
import time
from pathlib import Path
from typing import Any

try:
    import requests
except ImportError as exc:  # pragma: no cover
    raise SystemExit("Missing dependency: requests. Run `pip install -r requirements.txt`.") from exc

try:
    from dotenv import load_dotenv
except Exception:  # pragma: no cover
    load_dotenv = None

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "data"
OUTPUT = ROOT / "output"
NOTION_VERSION = os.getenv("NOTION_VERSION", "[REDACTED_PHONE]")
PACK_ID = "alipay-88vip-notion-pack-2026H2-v1"
DEFAULT_TARGET_URL = "http[REDACTED_LOCAL_PATH]"


def read_csv(name: str) -> list[dict[str, str]]:
    with (DATA / name).open("r", encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))


def parse_page_id(value: str) -> str:
    """Extract and hyphenate a Notion page ID from a URL or raw ID."""
    # Strip query/fragment, then find the last 32 hex chars.
    compact_candidates = re.findall(r"[0-9a-fA-F]{32}", value.replace("-", ""))
    if not compact_candidates:
        raise ValueError(f"Could not parse a 32-character Notion page ID from: {value}")
    compact = compact_candidates[-1].lower()
    return f"{compact[:8]}-{compact[8:12]}-{compact[12:16]}-{compact[16:20]}-{compact[20:]}"


def rt(text: str) -> list[dict[str, Any]]:
    if text is None:
        text = ""
    text = str(text)
    # Notion rich_text text.content max is 2000 chars. Chunk conservatively.
    chunks = [text[i:i+1800] for i in range(0, len(text), 1800)] or [""]
    return [{"type": "text", "text": {"content": chunk}} for chunk in chunks]


def title_prop(text: str) -> dict[str, Any]:
    return {"title": rt(text)}


def rich_text_prop(text: str) -> dict[str, Any]:
    return {"rich_text": rt(text)}


def select_prop(name: str) -> dict[str, Any]:
    return {"select": {"name": name[:100] if name else ""}}


def multi_select_prop(values: str) -> dict[str, Any]:
    if not values:
        return {"multi_select": []}
    parts = [v.strip() for v in re.split(r"[;；,，]", values) if v.strip()]
    return {"multi_select": [{"name": p[:100]} for p in parts]}


def checkbox_prop(value: str | bool) -> dict[str, Any]:
    if isinstance(value, bool):
        val = value
    else:
        val = str(value).strip().lower() in {"true", "1", "yes", "y", "是"}
    return {"checkbox": val}


def date_prop(iso: str) -> dict[str, Any]:
    return {"date": {"start": iso}}


def url_prop(url: str) -> dict[str, Any]:
    return {"url": url or None}


class NotionClient:
    def __init__(self, token: str, version: str = NOTION_VERSION, dry_run: bool = False):
        self.token = token
        self.version = version
        self.dry_run = dry_run
        self.base = "http[REDACTED_LOCAL_PATH]"
        self.session = requests.Session()
        self.session.headers.update({
            "Authorization": f"Bearer {token}",
            "Notion-Version": version,
            "Content-Type": "application/json",
        })

    def request(self, method: str, path: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        url = f"{self.base}{path}"
        if self.dry_run:
            print(f"DRY-RUN {method} {path}")
            if payload:
                print(json.dumps(payload, ensure_ascii=False)[:1200])
            return {"object": "dry_run", "id": "dry-run-id"}
        resp = self.session.request(method, url, json=payload, timeout=60)
        if resp.status_code >= 400:
            raise RuntimeError(f"Notion API error {resp.status_code} {method} {path}: {resp.text}")
        time.sleep(0.35)  # mild rate-limit protection
        return resp.json()

    def create_page(self, parent_page_id: str, title: str, children: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "parent": {"type": "page_id", "page_id": parent_page_id},
            "properties": {"title": title_prop(title)["title"]},
        }
        if children:
            payload["children"] = children
        return self.request("POST", "/pages", payload)

    def create_database(self, parent_page_id: str, title: str, properties: dict[str, Any], description: str = "") -> tuple[str, str | None]:
        payload = {
            "parent": {"type": "page_id", "page_id": parent_page_id},
            "title": rt(title),
            "description": rt(description),
            "is_inline": True,
            "initial_data_source": {"properties": properties},
        }
        db = self.request("POST", "/databases", payload)
        database_id = db.get("id", "dry-run-database-id")
        data_source_id = self.extract_data_source_id(db)
        if not data_source_id and not self.dry_run:
            retrieved = self.request("GET", f"/databases/{database_id}")
            data_source_id = self.extract_data_source_id(retrieved)
        return database_id, data_source_id

    @staticmethod
    def extract_data_source_id(obj: dict[str, Any]) -> str | None:
        if not obj:
            return None
        if isinstance(obj.get("initial_data_source"), dict) and obj["initial_data_source"].get("id"):
            return obj["initial_data_source"]["id"]
        ds = obj.get("data_sources")
        if isinstance(ds, list) and ds and ds[0].get("id"):
            return ds[0]["id"]
        if obj.get("object") == "data_source" and obj.get("id"):
            return obj["id"]
        return None

    def create_row(self, data_source_id: str, properties: dict[str, Any], children: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "parent": {"type": "data_source_id", "data_source_id": data_source_id},
            "properties": properties,
        }
        if children:
            payload["children"] = children
        return self.request("POST", "/pages", payload)

    def append_children(self, block_id: str, children: list[dict[str, Any]]) -> None:
        for i in range(0, len(children), 90):
            self.request("PATCH", f"/blocks/{block_id}/children", {"children": children[i:i+90]})


