                    "resource_type": infer_resource_type(name),
                    "resource_id": url,
                    "original_filename": name,
                    "download_methods": ["http_get_public_url"],
                }
            )
    return candidates


def extract_candidates_from_message(msg: dict[str, Any], group: dict[str, Any]) -> list[dict[str, Any]]:
