        print(json.dumps(result, ensure_ascii=False, indent=None if args.quiet else 2))
        return 0
    if args.dry_run:
        result["synced"] = False
        result["reason"] = "dry_run"
        print(json.dumps(result, ensure_ascii=False, indent=None if args.quiet else 2))
        return 0

