    if mode == "manual_only":
        return "manual_only"
    if str(group.get("group_type", "standing")) != "project":
        return mode
    completed = parse_date_value(group.get("completed_date"))
    if completed is None:
        return mode
    grace_days = int(group.get("grace_days", 7) or 7)
