    with manifest.open(newline="", encoding="utf-8") as f:
        return any((row.get("status") or "") in SUCCESS_STATUSES for row in csv.DictReader(f))


def mirror_manifest_has_success(zf: zipfile.ZipFile, prefix: str) -> bool:
